// Prüft die Entwürfe gegen die Quelle und baut die Telegram-Nachrichten.
const quelle = $('Regeln: Quelle prüfen (ohne KI)').first().json;
const fakten = $('Fakten lesen').first().json.fakten;

let roh = $input.first().json.text || '';
roh = roh.replace(/```json/gi, '').replace(/```/g, '').trim();
let e;
try {
  e = JSON.parse(roh);
} catch (err) {
  throw new Error('Die KI hat kein gültiges JSON geliefert (Entwürfe). Antwort: ' + roh.slice(0, 300));
}

// Text vereinheitlichen, damit Leerzeichen und Anführungszeichen den Vergleich nicht stören
const norm = (t) => String(t || '')
  .replace(/[„“”"«»‚‘’']/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();
const quellNorm = norm(quelle.quelltext);

const xThread = Array.isArray(e.x_thread) ? e.x_thread : [String(e.x_thread || '')];
const email = e.email || {};
const alleTexte = [e.instagram, e.linkedin, xThread.join('\n'), e.newsletter, e.video_skript, email.betreff, email.text].join('\n');

const hinweise = [];

// 1) Zitat-Prüfung: Jedes Zitat in „...“ muss wörtlich in der Quelle stehen
const zitate = [...alleTexte.matchAll(/„([^“”"]{8,})[“”"]/g)].map(m => m[1]);
for (const z of zitate) {
  if (!quellNorm.includes(norm(z))) hinweise.push('Zitat nicht wörtlich in der Quelle: „' + z + '“');
}

// 2) Gesperrtes Material darf nicht vorkommen
for (const sperre of fakten.nicht_verwenden) {
  const stueck = norm(sperre).split(' ').slice(0, 6).join(' ');
  if (stueck.length > 10 && norm(alleTexte).includes(stueck)) {
    hinweise.push('Gesperrtes Material verwendet: ' + sperre);
  }
}

// 3) X-Thread: Länge pro Tweet prüfen
xThread.forEach((t, i) => {
  if (t.length > 280) hinweise.push('Tweet ' + (i + 1) + ' ist zu lang (' + t.length + ' Zeichen)');
});


// 5) FESTE REGEL: Pflichtaussagen ([[EXAKT]]) müssen wörtlich oder gar nicht vorkommen
const regeln = $('Regeln: Quelle prüfen (ohne KI)').first().json;
const normW = t => String(t || '').replace(/[„“”«»"]/g, '"').replace(/[‚‘’]/g, "'").replace(/\s+/g, ' ').trim();
const alleNorm = normW(alleTexte);
const wortListe = (t, min) => [...new Set((normW(t).toLowerCase().match(/[a-zäöüß]+|\d+(?:[.,:]\d+)*/g) || []).filter(w => /\d/.test(w) || w.length >= min))];
const hatWort = (t, w) => new RegExp('(^|[^a-zäöüß0-9])' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^a-zäöüß0-9])', 'i').test(t);
let pflichtOk = 0;
for (const p of regeln.pflichtaussagen) {
  const P = normW(p);
  if (alleNorm.includes(P)) { pflichtOk++; continue; }
  const kw = wortListe(P, 7);
  if (kw.length && kw.filter(w => hatWort(alleNorm, w)).length / kw.length >= 0.6) hinweise.push('Pflichtaussage verändert: „' + P.slice(0, 60) + '…“');
}
// 6) FESTE REGEL: Wörter, die nur in internen Abschnitten stehen, dürfen nicht auftauchen
const quelleKlein = normW(quelle.quelltext).toLowerCase();
const leck = wortListe(regeln.intern_abschnitte.join(' '), 6).filter(w => !hatWort(quelleKlein, w) && hatWort(alleNorm, w));
if (leck.length) hinweise.push('Internes Material im Text: ' + leck.slice(0, 5).join(', '));

// 4) Unsichere Stellen zählen
const pruefen = (alleTexte.match(/\[PRÜFEN\]/g) || []).length;

const kopf = '⚡ NEUE ENTWÜRFE: ' + quelle.titel + '\n'
  + (quelle.videoUrl ? 'Video: ' + quelle.videoUrl + '\n' : '')
  + (quelle.bild ? 'Bild: ' + quelle.bild + '\n' : '')
  + '\nInterne Abschnitte entfernt: ' + quelle.intern_entfernt + ' | Pflichtaussagen wörtlich: ' + pflichtOk + '/' + regeln.pflichtaussagen.length
  + '\nMarkiert mit [PRÜFEN]: ' + pruefen
  + '\nAutomatische Prüfung: ' + (hinweise.length ? '⚠️ ' + hinweise.length + ' Hinweis(e)\n- ' + hinweise.join('\n- ') : '✅ keine Auffälligkeiten');

const nachrichten = [
  kopf,
  '📸 INSTAGRAM\n\n' + e.instagram,
  '💼 LINKEDIN\n\n' + e.linkedin,
  '🐦 X-THREAD\n\n' + xThread.map((t, i) => (i + 1) + '/ ' + t).join('\n\n'),
  '📰 NEWSLETTER\n\n' + e.newsletter,
  '🎬 KURZVIDEO-SKRIPT\n\n' + e.video_skript,
  '✉️ E-MAIL\nBetreff: ' + email.betreff + '\n\n' + email.text,
];

return nachrichten.map(n => ({
  json: {
    nachricht: n.slice(0, 4000),
    entwuerfe: e,
    hinweise,
    pruefenAnzahl: pruefen,
    pflichtOk,
  }
}));

// FESTE REGELN, KEINE KI: Quelle prüfen, interne Abschnitte entfernen, Pflichtaussagen merken.
const q = $input.first().json;
const text = String(q.quelltext || '');
const MIN_WOERTER = 200;
const woerter = t => (String(t).trim().match(/\S+/g) || []).length;

const intern = [], exakt = [];
let sauber = text.replace(/\[\[INTERN\]\]([\s\S]*?)\[\[\/INTERN\]\]/g, (m, a) => { intern.push(a.trim()); return ''; });
const offen = /\[\[\/?INTERN\]\]/.test(sauber) || intern.some(b => b.includes('[[INTERN]]')) ||
  (sauber.match(/\[\[EXAKT\]\]/g) || []).length !== (sauber.match(/\[\[\/EXAKT\]\]/g) || []).length;
sauber = sauber.replace(/\[\[EXAKT\]\]([\s\S]*?)\[\[\/EXAKT\]\]/g, (m, a) => { exakt.push(a.trim()); return a; })
  .replace(/\n{3,}/g, '\n\n').trim();

if (!text.trim()) throw new Error('STOPP: Keine Quelle bzw. keine Abschrift gefunden.');
if (offen) throw new Error('STOPP: Eine [[INTERN]]- oder [[EXAKT]]-Markierung ist nicht geschlossen. Abbruch, damit nichts Internes durchrutscht.');
if (woerter(sauber) < MIN_WOERTER) throw new Error('STOPP: Nach dem Entfernen interner Abschnitte bleiben nur ' + woerter(sauber) + ' Wörter (Minimum ' + MIN_WOERTER + ').');

return [{ json: { ...q, quelltext: sauber, quelle_original_woerter: woerter(text), quelle_woerter: woerter(sauber),
  intern_abschnitte: intern, intern_entfernt: intern.length, pflichtaussagen: exakt, start: Date.now() } }];

// Schreibt eine Zeile ins Protokoll (Google Sheets), egal ob freigegeben oder abgelehnt.
const q = $('Regeln: Quelle prüfen (ohne KI)').first().json;
const p = $('Prüfen & aufbereiten').first().json;
const ok = $('Freigabe am Handy').first().json.data?.approved === true;
return [{ json: {
  zeitpunkt: new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
  titel: q.titel, herkunft: q.herkunft, video: q.videoUrl || '',
  quelle_woerter: q.quelle_woerter, intern_entfernt: q.intern_entfernt,
  pflichtaussagen: q.pflichtaussagen.length, pflicht_woertlich: p.pflichtOk ?? '',
  hinweise: p.hinweise.length, pruefen_markierungen: p.pruefenAnzahl,
  entscheidung: ok ? 'freigegeben' : 'abgelehnt',
  minuten_bis_entscheidung: Math.round((Date.now() - q.start) / 6000) / 10
}}];
